with.code:
const out = $json.output || $json;
const note = out.set_coherence_note || '';
const neg = $('Envelope In').first().json.payload?.profile?.creative?.image_negative || '';
const prompts = (out.prompts || []).map((p, i) => ({
  ...p,
  index: i,
  prompt: note ? `${p.prompt}\n\nConsistent across set: ${note}` : p.prompt,
  negative_prompt: [p.negative_prompt, neg].filter(Boolean).join(', ')
}));
return prompts.map(p => ({ json: p }));
